// A simple resource to track its lifetime
class Resource {
public:
    Resource() { std::cout << "Resource created\n"; }
    ~Resource() { std::cout << "Resource destroyed\n"; }
};

// Demonstrating shared ownership
{ // Inner scope
    std::shared_ptr<Resource> sp1 = std::make_shared<Resource>();
    std::cout << "Count: " << sp1.use_count() << std::endl; // Count: 1

    std::shared_ptr<Resource> sp2 = sp1; // Copying increments the count
    std::cout << "Count: " << sp1.use_count() << std::endl; // Count: 2
} // sp2 goes out of scope, count decrements to 1. Resource is NOT destroyed.
// sp1 goes out of scope, count decrements to 0. Resource IS destroyed.

// DANGER: Creating multiple shared_ptrs from a raw pointer
Resource* raw_ptr = new Resource();
// std::shared_ptr<Resource> p1(raw_ptr); // OK, count is 1
// std::shared_ptr<Resource> p2(raw_ptr); // DANGEROUS! Creates a second control block.
// When p1 goes out of scope, Resource is deleted.
// When p2 goes out of scope, Resource is deleted AGAIN (undefined behavior).
